export default function ReferrerSeed() {
  const [status, setStatus] = useState('idle')
  const [log, setLog] = useState([])

  function addLog(msg) { setLog(prev => [...prev, msg]) }

  async function runSeed() {
    setStatus('running')
    setLog([])
    try {
      addLog('Loading current marketing data from Supabase...')
      const marketingCloud = await sbLoadMarketing()
      const fromMarketing = marketingCloud?.referrers || []
      addLog(`Supabase marketing table has: ${fromMarketing.length} referrers`)

      // Build master set from our local data (most complete)
      const seen = new Set(MASTER_CONTACTS.map(c => c.name.trim().toLowerCase()))
      addLog(`Master dataset: ${MASTER_CONTACTS.length} contacts`)

      // Add anything from Supabase not already in our master set
      const extras = fromMarketing.filter(c => !seen.has((c.name||'').trim().toLowerCase()))
      addLog(`Additional contacts found only in Supabase: ${extras.length}`)

      const final = [...MASTER_CONTACTS, ...extras]
      addLog(`Final total: ${final.length} referrers`)

      // Save to marketing table
      addLog('Saving to marketing table...')
      const payload = {
        ...(marketingCloud || {}),
        referrers: final,
      }
      await sbSaveMarketing(payload)

      // Save to referrers table too (keep in sync)
      addLog('Saving to referrers table...')
      await sbSaveReferrers(final)

      // Update localStorage
      localStorage.setItem('rion-marketing-referrers', JSON.stringify(final))
      addLog(`✅ Done! ${final.length} referrers saved to Supabase and localStorage.`)
      setStatus('done')
    } catch (err) {
      addLog(`❌ Error: ${err.message}`)
      setStatus('error')
    }
  }

  const C = { navy: '#3D4F6B', pink: '#EB99C2', white: '#fff', bg: '#2A3545', text: '#e8eaf0', muted: '#7A8090' }

  return (
    <div style={{ minHeight: '100vh', background: C.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'Montserrat, sans-serif', padding: 24 }}>
      <div style={{ background: C.navy, borderRadius: 12, padding: 40, maxWidth: 600, width: '100%', boxShadow: '0 8px 32px rgba(0,0,0,0.3)' }}>
        <div style={{ fontSize: 22, fontWeight: 700, color: C.white, marginBottom: 8 }}>Referrer Master Restore</div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 28 }}>
          Restores the full <strong style={{ color: C.pink }}>{MASTER_CONTACTS.length} contact</strong> dataset
          (original 169 with full detail + 154 new, deduped) into Supabase.
          Any contacts already in Supabase not in this set will also be preserved.
        </div>

        {(status === 'idle' || status === 'error') && (
          <button onClick={runSeed}
            style={{ background: C.pink, color: '#2A3545', border: 'none', borderRadius: 8, padding: '12px 28px', fontWeight: 700, fontSize: 14, cursor: 'pointer', fontFamily: 'Montserrat, sans-serif' }}>
            {status === 'error' ? 'Retry' : 'Restore All Contacts'}
          </button>
        )}

        {status === 'running' && (
          <div style={{ color: C.muted, fontSize: 13 }}>Running — please wait...</div>
        )}

        {log.length > 0 && (
          <div style={{ marginTop: 24, background: '#1a2233', borderRadius: 8, padding: 16 }}>
            {log.map((l, i) => (
              <div key={i} style={{ fontSize: 12, color: l.startsWith('✅') ? C.pink : l.startsWith('❌') ? '#f87171' : C.text, marginBottom: 6 }}>{l}</div>
            ))}
          </div>
        )}

        {status === 'done' && (
          <div style={{ marginTop: 20 }}>
            <div style={{ color: C.pink, fontWeight: 600, marginBottom: 12 }}>
              All done. Delete ReferrerSeed.jsx and remove the route from App.jsx.
            </div>
            <a href="/marketing" style={{ color: C.white, fontSize: 13 }}>→ Go to Marketing</a>
          </div>
        )}
      </div>
    </div>
  )
}
